      de: ["Die Mangroven auf Kamaran bestehen hauptsächlich aus der Art Avicennia marina.", "Die Insel Kamaran ist die größte jemenitische Insel im Roten Meer.", "Mangrovenwälder können bis zu viermal mehr Kohlenstoff speichern als Regenwälder.", "Über 20 verschiedene Vogelarten nutzen die Mangroven als Brutstätte.", "Die Wurzeln der Mangroven filtern Salz aus dem Meerwasser.", "Kamaran war historisch eine wichtige Quarantänestation für Mekka-Pilger."],
      hu: ["A kamaran-i mangrovék főként az Avicennia marina fajhoz tartoznak.", "Kamaran a legnagyobb jemenit sziget a Vörös-tengeren.", "A mangroveerdők akár négyszer több szenet képesek megkötni, mint az esőerdők.", "Több mint 20 különböző madárfaj használja fészkelőhelyként a mangrovékat.", "A mangrovék gyökerei kiszűrik a sót a tengervízből.", "Kamaran történelmileg fontos karanténállomás volt a Mekkába tartó zarándokoknak."],
      ro: ["Mangrovele din Kamaran aparțin în principal speciei Avicennia marina.", "Insula Kamaran este cea mai mare insulă yemenită din Marea Roșie.", "Pădurile de mangrove pot stoca de până la patru ori mai mult carbon decât pădurile tropicale.", "Peste 20 de specii de păsări folosesc mangrovele ca loc de cuibărit.", "Rădăcinile mangrovelor filtrează sarea din apa de mare.", "Kamaran a fost istoric o stație de carantină importantă pentru pelerinii spre Mecca."],
      en: ["The mangroves on Kamaran predominantly consist of the Avicennia marina species.", "Kamaran is the largest Yemeni island located within the Red Sea.", "Mangrove forests can sequester up to four times more carbon than tropical rainforests.", "Over 20 different bird species utilize the mangroves as a seasonal breeding ground.", "Mangrove root systems are capable of filtering salt directly from seawater.", "Kamaran historically served as a major quarantine station for pilgrims to Mecca."],
      es: ["Isla Kamaran: superficie de unos 108 km²", "Especie principal: Avicennia marina", "Distancia de la costa: unos 30 km", "Amenazada por la contaminación petrolera", "Hábitat de aves migratorias", "Protección contra la erosión costera"],
      pt: ["Ilha Kamaran: área de cerca de 108 km²", "Espécie principal: Avicennia marina", "Distância da costa: cerca de 30 km", "Ameaçada pela poluição por petróleo", "Habitat de aves migratórias", "Proteção contra a erosão costeira"],
      fr: ["Île de Kamaran : superficie d'environ 108 km²", "Espèce principale : Avicennia marina", "Distance de la côte : environ 30 km", "Menacé par la pollution pétrolière", "Habitat pour les oiseaux migrateurs", "Protection contre l'érosion côtière"],
